const r = await tools.exec_command({
  cmd: "$ErrorActionPreference = 'Stop'
Write-Output ('CODEX_THREAD_ID=' + $env:CODEX_THREAD_ID)
Write-Output ('CWD=' + (Get-Location).Path)
$gitStatus = @(git status --short)
Write-Output ('GIT_STATUS_COUNT=' + $gitStatus.Count)
$gitStatus | Group-Object { $_.Substring(0,2) } | ForEach-Object { Write-Output ('GIT_STATUS_CATEGORY=' + $_.Name + ':' + $_.Count) }
rg --files -g '*fingerprint*' -g '*BuildProfile*' -g '*final.diff*' -g '*AGENTS.md' -g '*state.json' -g '*implementation*' -g '*submission*' -g '!oh_modules/**' -g '!entry/build/**' -g '!build/**' -g '!.git/**' -g '!traces/**' -g '!native/**' -g '!inputs/**' -g '!hvigor/**' -g '!workflow/logs/**' .",
  workdir: "D:/HCUP/vg-spec13",
  max_output_tokens: 5000
}); text(r.output);

const results = await Promise.allSettled([
  tools.exec_command({
    cmd:"$ErrorActionPreference = 'Stop'
Write-Output 'OFFICIAL_CHECKLIST'
Get-Content -LiteralPath 'D:/SWE-OpenHarmony/templates/submission-checklist.md' -Raw
Write-Output 'COLLECTOR_ALGORITHM'
Get-Content -LiteralPath 'workflow/implementation/collect-evidence-v2.py' -TotalCount 90
Write-Output 'SUBMISSION_DRAFT_EXISTS'
Test-Path -LiteralPath '.comate/submission-draft/audits/implementation-freeze.md'
if (Test-Path -LiteralPath '.comate/submission-draft/audits/implementation-freeze.md') { Get-Content -LiteralPath '.comate/submission-draft/audits/implementation-freeze.md' -Raw }",
    workdir:"D:/HCUP/vg-spec13",max_output_tokens:8000
  }),
  tools.exec_command({
    cmd:"$ErrorActionPreference = 'Stop'
$untracked = @(git -c core.quotepath=false ls-files --others --exclude-standard)
Write-Output ('UNTRACKED_FILE_COUNT=' + $untracked.Count)
$untracked | Group-Object { ($_ -split '/')[0] } | Sort-Object Name | ForEach-Object { Write-Output ('UNTRACKED_TOP=' + $_.Name + ':' + $_.Count) }
Write-Output 'BUILDPROFILE_TRACKING'
$allTracked = @(git -c core.quotepath=false ls-files)
$allTracked | Where-Object { $_ -match '(^|/)BuildProfile\.(ets|ts)$' } | ForEach-Object { Write-Output ('TRACKED_BUILDPROFILE=' + $_) }
$buildProfiles = @(Get-ChildItem -LiteralPath 'entry' -Recurse -File -Filter 'BuildProfile.ets' -ErrorAction SilentlyContinue)
Write-Output ('WORKTREE_BUILDPROFILE_COUNT=' + $buildProfiles.Count)
$buildProfiles | ForEach-Object { $relative = $_.FullName.Substring((Get-Location).Path.Length + 1).Replace('\','/'); Write-Output ('BUILDPROFILE=' + $relative); git check-ignore -v -- $relative }
Write-Output 'DRAFT_IGNORE_RULE'
git check-ignore -v -- '.comate/submission-draft/audits/implementation-freeze.md'
Write-Output 'BASE_REQUIRED_PATHS'
foreach ($taskPath in @('spec','hypium_tests','workflow','logs','traces','system-config','test-harness','spec-harness','inputs','.comate')) {
  $count = @($allTracked | Where-Object { $_ -eq $taskPath -or $_.StartsWith($taskPath + '/') }).Count
  Write-Output ('BASE_TRACKED=' + $taskPath + ':' + $count)
}
Write-Output 'FORBIDDEN_TRACE_FILENAMES_ONLY'
$nativeRoot = 'traces/native'
if (Test-Path -LiteralPath $nativeRoot) {
  $matches = @(Get-ChildItem -LiteralPath $nativeRoot -Recurse -File | Where-Object { $_.FullName.Contains('01a13fc4-2611-7761-a580-1283e0c70541') })
  Write-Output ('INITIALIZATION_OVERVIEW_NAMED_FILES=' + $matches.Count)
  $matches | Select-Object -First 10 | ForEach-Object { Write-Output $_.FullName.Substring((Get-Location).Path.Length + 1).Replace('\','/') }
}",
    workdir:"D:/HCUP/vg-spec13",max_output_tokens:4000
  })
]); for(let i=0;i<results.length;i++){text({i,status:results[i].status});text(results[i].status==="fulfilled"?results[i].value.output:String(results[i].reason));}

