const r = await tools.exec_command({
  cmd:"$ErrorActionPreference = 'Stop'
@'
from pathlib import Path
import hashlib
import json
from datetime import datetime, timezone
root = Path.cwd()
manifest = json.loads((root / 'workflow/implementation/source-fingerprint-v2.json').read_text(encoding='utf-8-sig'))
actual = {path: hashlib.sha256((root/path).read_bytes()).hexdigest() for path in manifest['tracked_plus_authorized_new_files_sha256']}
aggregate = hashlib.sha256(json.dumps(actual, sort_keys=True, separators=(',', ':')).encode('utf-8')).hexdigest()
print('AUDIT_TIME_UTC=' + datetime.now(timezone.utc).isoformat())
print('CURRENT_AGGREGATE=' + aggregate)
print('AGGREGATE_MATCH=' + str(aggregate == manifest['aggregate_sha256']))
print('AUTHORIZED_PRODUCTION_FILE_COUNT=' + str(len(manifest['authorized_production_files_sha256'])))
for path in manifest['authorized_production_files_sha256']:
    print('PRODUCTION_SHA256=' + path + ':' + actual[path])
'@ | python -
Write-Output 'UNTRACKED_PRODUCTION_LINE_COUNTS'
foreach ($taskPath in @('entry/src/main/ets/pages/settings/SettingsNavigationBuilders.ets','entry/src/main/ets/pages/settings/SettingsWebDavBuilders.ets','entry/src/main/ets/sync/ManualWebDavBackupController.ets')) {
  Write-Output ($taskPath + ':' + @(Get-Content -LiteralPath $taskPath).Count)
}
Write-Output 'DRAFT_STATUS'
if (Test-Path -LiteralPath '.comate/submission-draft') { Get-ChildItem -LiteralPath '.comate/submission-draft' -Force | Select-Object Name,Mode }",
  workdir:"D:/HCUP/vg-spec13",max_output_tokens:3000
});text(r.output);

const r = await tools.exec_command({
  cmd:"$ErrorActionPreference = 'Stop'
Write-Output ('AUDIT_FILE_EXISTS=' + (Test-Path -LiteralPath '.comate/submission-draft/audits/implementation-freeze.md' -PathType Leaf))
Write-Output ('AUDIT_SHA256=' + (Get-FileHash -LiteralPath '.comate/submission-draft/audits/implementation-freeze.md' -Algorithm SHA256).Hash.ToLowerInvariant())
rg -n '^fingerprints =|^aggregate =' workflow/implementation/collect-evidence-v2.py
$trackedStatus = @(git status --porcelain --untracked-files=no)
Write-Output ('TRACKED_CHANGED_AFTER_AUDIT=' + $trackedStatus.Count)
$fp = Get-Content -LiteralPath 'workflow/implementation/source-fingerprint-v2.json' -Raw | ConvertFrom-Json
$mismatchCount = 0
foreach ($prop in $fp.tracked_plus_authorized_new_files_sha256.PSObject.Properties) { if ((Get-FileHash -LiteralPath $prop.Name -Algorithm SHA256).Hash.ToLowerInvariant() -ne $prop.Value) { $mismatchCount++ } }
Write-Output ('FINAL_SOURCE_MISMATCH_COUNT=' + $mismatchCount)",
  workdir:"D:/HCUP/vg-spec13",max_output_tokens:1500
}); text(r.output);
